import { createHash, randomUUID } from 'node:crypto';
import { createReadStream } from 'node:fs';
import { link, lstat, open, unlink } from 'node:fs/promises';
import { createInterface } from 'node:readline';
import { createRequire } from 'node:module';

const ENV_FILE = '/Users/gallivan/Code/WMKF_Apps/.env.local';
const PATHNAME = 'stage4/ffmpeg-n9.0.2-23-g27b46f0fbc-linux64-gpl-9.0.tar.xz';
const EXPECTED_SHA256 = '14020417ff8ef01470e8cb771355e65c37aff62b80fb0be41eeb7611d1360902';
const MAX_BYTES = 192 * 1024 * 1024;
const FINAL_FILE = '/private/tmp/wmkf-media-investigation-qx7b5evb/ffmpeg-n9.0.2-23-g27b46f0fbc-linux64-gpl-9.0.tar.xz';
const require = createRequire('/Users/gallivan/Code/WMKF_Apps/package.json');

async function readOnlyUploadsToken() {
  let token;
  const lines = createInterface({ input: createReadStream(ENV_FILE), crlfDelay: Infinity });
  for await (const line of lines) {
    if (!line.startsWith('UPLOADS_BLOB_RW_TOKEN=')) continue;
    if (token !== undefined) throw new Error('duplicate_token');
    token = line.slice('UPLOADS_BLOB_RW_TOKEN='.length).trim();
    if (token.startsWith('"') && token.endsWith('"')) token = token.slice(1, -1);
  }
  if (!token) throw new Error('missing_token');
  return token;
}

let stage = 'local_preflight';
try {
  try {
    await lstat(FINAL_FILE);
    throw new Error('local_archive_already_exists');
  } catch (error) {
    if (error?.code !== 'ENOENT') throw error;
  }

  stage = 'local_setup';
  const token = await readOnlyUploadsToken();
  process.env.VERCEL_BLOB_RETRIES = '0';
  const { head, get } = require('@vercel/blob');

  stage = 'metadata';
  const metadata = await head(PATHNAME, { token, abortSignal: AbortSignal.timeout(30_000) });
  if (metadata.pathname !== PATHNAME || !Number.isSafeInteger(metadata.size) ||
      metadata.size <= 0 || metadata.size > MAX_BYTES) throw new Error('metadata_rejected');

  stage = 'content';
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 180_000);
  try {
    const result = await get(PATHNAME, {
      access: 'private', token, useCache: false, abortSignal: controller.signal,
    });
    if (result?.statusCode !== 200 || !result.stream ||
        result.blob.pathname !== PATHNAME || result.blob.size !== metadata.size ||
        (metadata.etag && result.blob.etag && metadata.etag !== result.blob.etag)) {
      throw new Error('content_metadata_rejected');
    }

    const hash = createHash('sha256');
    const reader = result.stream.getReader();
    let bytes = 0;
    const partialFile = `${FINAL_FILE}.part-${process.pid}-${randomUUID()}`;
    const handle = await open(partialFile, 'wx', 0o600);
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        bytes += value.byteLength;
        if (bytes > MAX_BYTES || bytes > metadata.size) {
          controller.abort();
          throw new Error('content_too_large');
        }
        hash.update(value);
        const chunk = Buffer.from(value);
        let offset = 0;
        while (offset < chunk.length) {
          const written = await handle.write(chunk, offset, chunk.length - offset, null);
          if (written.bytesWritten <= 0) throw new Error('local_write_failed');
          offset += written.bytesWritten;
        }
      }
      if (bytes !== metadata.size || hash.digest('hex') !== EXPECTED_SHA256) {
        throw new Error('content_hash_or_size_mismatch');
      }
      await handle.sync();
      await handle.close();
      // link() is atomic and refuses an existing final file; it cannot overwrite one.
      await link(partialFile, FINAL_FILE);
      await unlink(partialFile);
      console.log(`PASS: sha256_match=true bytes=${bytes} archive_retained=true`);
    } catch (error) {
      controller.abort();
      await handle.close().catch(() => {});
      await unlink(partialFile).catch(() => {});
      throw error;
    } finally {
      reader.releaseLock();
    }
  } finally {
    controller.abort();
    clearTimeout(timer);
  }
} catch {
  // Avoid printing SDK exceptions, local environment content, tokens, or Blob URLs.
  console.error(`FAIL: ${stage}; no content retained`);
  process.exitCode = 1;
}
